```tsx
import { useId } from "react";
import type { ChangeEvent } from "react";
import "./TextField.css";

export interface TextFieldProps {
  label: string;
  value: string;
  onChange: (value: string) => void;
  error?: string;
  placeholder?: string;
}

export function TextField({ label, value, onChange, error, placeholder }: TextFieldProps) {
  const id = useId();
  const errorId = `${id}-error`;
  const hasError = Boolean(error);

  return (
    <div className={hasError ? "text-field is-invalid" : "text-field"}>
      <label className="text-field-label" htmlFor={id}>
        {label}
      </label>
      <input
        id={id}
        type="text"
        className="text-field-input"
        value={value}
        placeholder={placeholder}
        onChange={(event: ChangeEvent<HTMLInputElement>) => onChange(event.target.value)}
        aria-invalid={hasError ? true : undefined}
        aria-describedby={hasError ? errorId : undefined}
      />
      {hasError && (
        <p id={errorId} className="text-field-error" role="alert">
          {error}
        </p>
      )}
    </div>
  );
}
```

