.text-field {
  display: grid;
  gap: 6px;
  font: inherit;
}

.text-field-label {
  color: var(--ink);
  font: inherit;
  font-size: clamp(0.875rem, 0.8rem + 0.3vw, 1rem);
  font-weight: 600;
}

.text-field-input {
  font: inherit;
  font-size: clamp(0.9375rem, 0.85rem + 0.35vw, 1.125rem);
  color: var(--ink);
  background: var(--slide);
  border: 1px solid var(--muted);
  border-radius: 8px;
  padding: 0.6em 0.8em;
  transition: border-color 150ms ease, border-width 150ms ease;
}

.text-field-input::placeholder {
  color: var(--muted);
  opacity: 1;
}

.text-field-input:focus-visible {
  border-color: var(--cresyl);
}

.text-field.is-invalid .text-field-input {
  border-color: var(--cresyl);
  border-width: 2px;
}

.text-field-error {
  margin: 0;
  color: var(--cresyl);
  font-size: clamp(0.8125rem, 0.78rem + 0.2vw, 0.9375rem);
}

:root[data-motion="reduce"] .text-field-input {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .text-field-input {
    transition: none;
  }
}
